package com.repairconnect.controller;
import com.repairconnect.entity.*; import com.repairconnect.repository.*; import com.repairconnect.security.JwtService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users; private final CustomerRepository customers; private final ProviderRepository providers; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserRepository u,CustomerRepository c,ProviderRepository p,PasswordEncoder e,JwtService j){users=u;customers=c;providers=p;encoder=e;jwt=j;}
 record Registration(@NotBlank String fullName,@Email @NotBlank String email,@NotBlank String password,String phone,String address,String city,Integer experience,String description){}
 @PostMapping("/register/customer") ResponseEntity<?> customer(@Valid @RequestBody Registration r){return register(r,Role.CUSTOMER);} @PostMapping("/register/provider") ResponseEntity<?> provider(@Valid @RequestBody Registration r){return register(r,Role.SERVICE_PROVIDER);}
 private ResponseEntity<?> register(Registration r,Role role){if(users.findByEmail(r.email()).isPresent())throw new RuntimeException("Email is already registered"); User u=users.save(new User(r.fullName(),r.email(),encoder.encode(r.password()),r.phone(),role)); if(role==Role.CUSTOMER)customers.save(new CustomerProfile(u,r.address(),r.city())); else providers.save(new ProviderProfile(u,r.address(),r.city(),r.experience(),r.description())); return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("message","Registration successful"));}
 record Login(@Email String email,@NotBlank String password){} @PostMapping("/login") Map<String,Object> login(@Valid @RequestBody Login r){User u=users.findByEmail(r.email()).orElseThrow(()->new org.springframework.security.authentication.BadCredentialsException("Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword())||!u.isEnabled())throw new org.springframework.security.authentication.BadCredentialsException("Invalid email or password");return Map.of("token",jwt.create(u.getEmail(),u.getRole().name()),"user",Map.of("id",u.getId(),"name",u.getFullName(),"email",u.getEmail(),"role",u.getRole()));}
}